import json
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urldefrag, urlsplit

import framework_evidence

BASE = "http://192.168.2.1/"
ORIGIN = ("http", "192.168.2.1", 80)
TIMEOUT = "15"


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.hrefs = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "a":
            for key, value in attrs:
                if key.lower() == "href" and value:
                    self.hrefs.append(value)


def same_origin(url):
    parts = urlsplit(url)
    port = parts.port or (443 if parts.scheme == "https" else 80)
    return (parts.scheme, parts.hostname, port) == ORIGIN


def response_text(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs", [])
        if runs and isinstance(runs[0], dict):
            return runs[0].get("stdout", "")
    return ""


def request(url):
    argv = [
        "curl", "--silent", "--show-error", "--include", "--location",
        "--max-redirs", "5", "--max-time", TIMEOUT, "--", url,
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
        print(json.dumps({"attempted_url": url, "evidence": envelope}, ensure_ascii=False))
        return envelope
    except Exception as exc:
        print(json.dumps({"attempted_url": url, "error": str(exc)}, ensure_ascii=False))
        return None


def main():
    root_result = request(BASE)
    html = response_text(root_result) if root_result is not None else ""
    parser = LinkParser()
    try:
        parser.feed(html)
    except Exception:
        pass

    # Include links observed in the supplied root response, even if a fresh root
    # request is incomplete or does not return parseable HTML.
    discovered = [
        "index.php?#",
        "index.php?page=page1.php",
        "index.php?page=page2.php",
        "index.php?page=page3.php",
    ] + parser.hrefs

    seen = {BASE}
    for href in discovered:
        absolute, _fragment = urldefrag(urljoin(BASE, href))
        if same_origin(absolute) and absolute not in seen:
            seen.add(absolute)
            request(absolute)

    # Selected standard metadata, application, and directly relevant file paths.
    for path in (
        "/robots.txt",
        "/sitemap.xml",
        "/.well-known/security.txt",
        "/favicon.ico",
        "/login.php",
        "/admin/",
        "/flag.txt",
    ):
        url = urljoin(BASE, path)
        if url not in seen:
            seen.add(url)
            request(url)


if __name__ == "__main__":
    main()

