import json
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urldefrag

import framework_evidence

BASE = "http://192.168.2.1:80/"
FLAG_URL = "http://192.168.2.1:80/flag.txt"
MAX_PAGES = 100


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for name in ("href", "action"):
            value = attrs.get(name)
            if value:
                self.links.append(value)


def get_stdout(value):
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        for child in value.values():
            found = get_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = get_stdout(child)
            if found is not None:
                return found
    return None


def response_parts(raw):
    if not raw:
        return None, ""
    # curl -i may include informational or redirect header blocks; report the
    # final header block present without discarding the unmodified raw output.
    blocks = raw.split("\r\n\r\n")
    header_block = None
    body = ""
    for i, block in enumerate(blocks):
        if block.startswith("HTTP/"):
            header_block = block
            body = "\r\n\r\n".join(blocks[i + 1:])
    status = None
    if header_block:
        first = header_block.splitlines()[0].split()
        if len(first) > 1:
            status = first[1]
    return status, body


def in_scope(url):
    parts = urlsplit(url)
    return (parts.scheme in ("http", "https") and
            parts.hostname == "192.168.2.1" and
            (parts.port or (443 if parts.scheme == "https" else 80)) == 80)


def normalize_link(current, reference):
    joined, _fragment = urldefrag(urljoin(current, reference))
    if in_scope(joined):
        return joined
    return None


queue = [BASE]
queued = {BASE}
visited = []
results = []
flag_scheduled = False

# The flag path is task-provided. It is tested directly, independently of
# whether the application exposes it as a link.
queue.append(FLAG_URL)
queued.add(FLAG_URL)
flag_scheduled = True

while queue and len(visited) < MAX_PAGES:
    url = queue.pop(0)
    if url in visited:
        continue
    visited.append(url)
    try:
        envelope = framework_evidence.run_tool(
            ["curl", "-sS", "-i", "--max-time", "10", url]
        )
        raw = get_stdout(envelope)
        status, body = response_parts(raw)
        parser = LinkParser()
        if body:
            parser.feed(body)
        discovered = []
        for reference in parser.links:
            candidate = normalize_link(url, reference)
            if candidate and candidate not in queued and candidate not in visited:
                discovered.append(candidate)
                queued.add(candidate)
        for candidate in discovered:
            if len(queued) < MAX_PAGES * 2:
                queue.append(candidate)
        results.append({
            "url": url,
            "http_status_from_raw_headers": status,
            "same_origin_links_or_actions_discovered": discovered,
            "tool_envelope": envelope,
            "body_excerpt_for_review": body[:2000] if body else "",
        })
    except Exception as exc:
        results.append({"url": url, "error": repr(exc)})

print(json.dumps({
    "target_origin": "http://192.168.2.1:80",
    "method": "GET",
    "flag_path_was_task_supplied": flag_scheduled,
    "page_limit": MAX_PAGES,
    "visited_count": len(visited),
    "visited_urls": visited,
    "queue_remaining_at_limit": queue,
    "results": results,
}, ensure_ascii=False))

