import hashlib
import http.client
import json
from html.parser import HTMLParser

HOST = "192.168.2.1"
PATHS = [
    "/index.php?page=page1.php",
    "/index.php?page=page2.php",
    "/index.php?page=page3.php",
]

class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []

    def handle_starttag(self, tag, attrs):
        for key, value in attrs:
            if key in ("href", "src", "action") and value is not None:
                self.links.append({"tag": tag, "attribute": key, "value": value})


def request(path):
    requested_url = "http://" + HOST + path
    record = {"requested_url": requested_url}
    connection = http.client.HTTPConnection(HOST, 80, timeout=10)
    try:
        connection.request("GET", path, headers={"Host": HOST, "Connection": "close"})
        response = connection.getresponse()
        body_bytes = response.read()
        body = body_bytes.decode("utf-8", errors="replace")
        parser = LinkParser()
        try:
            parser.feed(body)
            parser.close()
            link_parse_error = None
        except Exception as exc:
            link_parse_error = str(exc)
        record.update({
            "status": response.status,
            "reason": response.reason,
            "headers": response.getheaders(),
            "body": body,
            "body_bytes_length": len(body_bytes),
            "body_sha256": hashlib.sha256(body_bytes).hexdigest(),
            "extracted_links": parser.links,
            "link_parse_error": link_parse_error,
        })
    except Exception as exc:
        record["request_error"] = {"type": type(exc).__name__, "message": str(exc)}
    finally:
        connection.close()
    return record


print(json.dumps({"host": HOST, "results": [request(path) for path in PATHS]}, ensure_ascii=False))

