import json
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit

import framework_evidence

BASE = "http://192.168.2.1/"


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "a" and attrs.get("href"):
            self.links.append(attrs["href"])
        elif tag.lower() == "form":
            self._form = {
                "action": attrs.get("action", ""),
                "method": attrs.get("method", "get").lower(),
                "controls": [],
            }
            self.forms.append(self._form)
        elif self._form is not None and tag.lower() in ("input", "button", "select", "textarea"):
            self._form["controls"].append({
                "tag": tag.lower(),
                "name": attrs.get("name"),
                "type": attrs.get("type"),
                "value": attrs.get("value"),
            })

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None


def find_stdout(value):
    if isinstance(value, dict):
        out = value.get("stdout")
        if isinstance(out, str):
            return out
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def main():
    try:
        envelope = framework_evidence.run_tool([
            "curl", "-sS", "--max-time", "15", "-D", "-", BASE
        ])
    except Exception as exc:
        print(json.dumps({
            "purpose": "Fetch the current homepage once; do not repeat unidentified prior page-link requests.",
            "tool_error": repr(exc),
            "prior_link_visit_status": "unknown: supplied observation is partial",
        }, ensure_ascii=False))
        return

    raw = find_stdout(envelope)
    parsed = {
        "parser": "stdlib_html_parser",
        "status": "not_parsed",
        "http_status_line": None,
        "same_origin_links": [],
        "same_origin_forms": [],
        "parse_error": None,
    }
    if raw is not None:
        separator = "\r\n\r\n"
        if separator in raw:
            headers, body = raw.split(separator, 1)
        elif "\n\n" in raw:
            headers, body = raw.split("\n\n", 1)
        else:
            headers, body = "", raw
        parsed["http_status_line"] = next(
            (line.strip() for line in headers.splitlines() if line.startswith("HTTP/")),
            None,
        )
        parser = PageParser()
        try:
            parser.feed(body)
            origin = urlsplit(BASE)

            def same_origin_url(value):
                absolute = urljoin(BASE, value)
                candidate = urlsplit(absolute)
                return absolute if (candidate.scheme, candidate.netloc) == (origin.scheme, origin.netloc) else None

            for href in parser.links:
                absolute = same_origin_url(href)
                if absolute is not None:
                    parsed["same_origin_links"].append({"href": href, "url": absolute})
            for form in parser.forms:
                absolute = same_origin_url(form["action"] or BASE)
                if absolute is not None:
                    parsed["same_origin_forms"].append({
                        "action": form["action"],
                        "url": absolute,
                        "method": form["method"],
                        "controls": form["controls"],
                    })
            parsed["status"] = "parsed"
        except Exception as exc:
            parsed["parse_error"] = repr(exc)
            parsed["status"] = "parser_error"
    else:
        parsed["status"] = "tool envelope had no discoverable stdout"

    print(json.dumps({
        "purpose": "Current homepage observation only; no discovered links were followed.",
        "request": ["curl", "-sS", "--max-time", "15", "-D", "-", BASE],
        "tool_envelope": envelope,
        "derived_response_observation": parsed,
        "prior_link_visit_status": "unknown: the supplied prior-observation evidence is partial and does not expose the three URLs or their request outcomes",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

