import json
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.parse import urljoin, urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener

BASE = "http://192.168.2.1/"
LINKS = [
    "http://192.168.2.1/index.php?page=page1.php",
    "http://192.168.2.1/index.php?page=page2.php",
    "http://192.168.2.1/index.php?page=page3.php",
]
TIMEOUT_SECONDS = 15


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self._form = None

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag.lower() == "a" and attributes.get("href") is not None:
            self.links.append({"href": attributes["href"], "text": ""})
            self._active_link = len(self.links) - 1
        elif tag.lower() == "form":
            self._form = {
                "action": attributes.get("action", ""),
                "method": attributes.get("method", "get").lower(),
                "enctype": attributes.get("enctype"),
                "controls": [],
            }
            self.forms.append(self._form)
        elif tag.lower() in ("input", "button", "select", "textarea") and self._form is not None:
            self._form["controls"].append({
                "tag": tag.lower(),
                "name": attributes.get("name"),
                "type": attributes.get("type"),
                "value": attributes.get("value"),
            })

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self._form = None
        if tag.lower() == "a":
            self._active_link = None

    def handle_data(self, data):
        index = getattr(self, "_active_link", None)
        if index is not None:
            self.links[index]["text"] += data


def same_origin(url):
    a, b = urlsplit(BASE), urlsplit(url)
    return (a.scheme.lower(), a.hostname, a.port or 80) == (b.scheme.lower(), b.hostname, b.port or 80)


def main():
    opener = build_opener(NoRedirect())
    results = []
    for url in LINKS:
        item = {"requested_url": url, "method": "GET"}
        try:
            request = Request(url, headers={"User-Agent": "evidence-collection/1.0"}, method="GET")
            try:
                response = opener.open(request, timeout=TIMEOUT_SECONDS)
            except HTTPError as exc:
                response = exc
            with response:
                body_bytes = response.read()
                body = body_bytes.decode("utf-8", errors="replace")
                item.update({
                    "outcome": "http_response",
                    "status": response.code,
                    "reason": getattr(response, "reason", ""),
                    "final_url": response.geturl(),
                    "headers": list(response.headers.items()),
                    "body": body,
                })
                parser = PageParser()
                try:
                    parser.feed(body)
                    parser.close()
                    item["html_parse_status"] = "parsed"
                    item["same_origin_links"] = [
                        {**link, "url": urljoin(response.geturl(), link["href"])}
                        for link in parser.links
                        if same_origin(urljoin(response.geturl(), link["href"]))
                    ]
                    item["other_origin_links"] = [
                        {**link, "url": urljoin(response.geturl(), link["href"])}
                        for link in parser.links
                        if not same_origin(urljoin(response.geturl(), link["href"]))
                    ]
                    item["forms"] = [
                        {**form, "resolved_action": urljoin(response.geturl(), form["action"])}
                        for form in parser.forms
                    ]
                except Exception as exc:
                    item["html_parse_status"] = "error"
                    item["html_parse_error"] = repr(exc)
        except (URLError, TimeoutError, OSError) as exc:
            item.update({"outcome": "request_error", "error": repr(exc)})
        except Exception as exc:
            item.update({"outcome": "unexpected_error", "error": repr(exc)})
        results.append(item)

    print(json.dumps({
        "target_origin": BASE,
        "request_coverage": {"requested": len(results), "results": results},
        "scope_note": "Only the three supplied same-origin page links were requested. Redirects were not followed. HTTP responses and parsed page elements are observations, not proof of system access or flag.txt access.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

