import html.parser
import json
import re
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://192.168.2.1:80/"
BASE_PARTS = urllib.parse.urlsplit(BASE)
BASE_ORIGIN = (BASE_PARTS.scheme, BASE_PARTS.hostname, BASE_PARTS.port)


def same_origin(url):
    try:
        parts = urllib.parse.urlsplit(url)
        return (parts.scheme, parts.hostname, parts.port or (80 if parts.scheme == "http" else 443)) == BASE_ORIGIN
    except ValueError:
        return False


def normalize(url, base):
    absolute = urllib.parse.urljoin(base, url)
    parts = urllib.parse.urlsplit(absolute)
    if parts.scheme not in ("http", "https") or not same_origin(absolute):
        return None
    return urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path or "/", parts.query, ""))


class SameOriginRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if not same_origin(newurl):
            return None
        return super().redirect_request(req, fp, code, msg, headers, newurl)


class PageParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.scripts = []
        self.forms = []
        self.current_form = None
        self.in_script = False
        self.script_text = []
        self.inline_scripts = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a" and attrs.get("href"):
            self.links.append(attrs["href"])
        elif tag == "script":
            if attrs.get("src"):
                self.scripts.append(attrs["src"])
            else:
                self.in_script = True
                self.script_text = []
        elif tag == "form":
            self.current_form = {
                "action": attrs.get("action", ""),
                "method": attrs.get("method", "get").lower(),
                "fields": [],
            }
            self.forms.append(self.current_form)
        elif tag == "input" and self.current_form is not None:
            typ = attrs.get("type", "text").lower()
            name = attrs.get("name")
            if name and typ not in ("submit", "button", "image", "reset", "file"):
                self.current_form["fields"].append((name, attrs.get("value", "")))

    def handle_endtag(self, tag):
        if tag == "script" and self.in_script:
            self.inline_scripts.append("".join(self.script_text))
            self.in_script = False
            self.script_text = []
        elif tag == "form":
            self.current_form = None

    def handle_data(self, data):
        if self.in_script:
            self.script_text.append(data)


def fetch(url):
    request = urllib.request.Request(url, headers={"User-Agent": "blog-workflow-observation/1.0"})
    try:
        with opener.open(request, timeout=8) as response:
            raw = response.read()
            headers = list(response.headers.items())
            status = response.status
            final_url = response.geturl()
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        headers = list(exc.headers.items()) if exc.headers else []
        status = exc.code
        final_url = exc.geturl()
    except Exception as exc:
        return {"requested_url": url, "error": type(exc).__name__ + ": " + str(exc)}

    charset = "utf-8"
    for key, value in headers:
        if key.lower() == "content-type":
            match = re.search(r"charset\s*=\s*[\"']?([^;\"' ]+)", value, re.I)
            if match:
                charset = match.group(1)
            break
    try:
        body = raw.decode(charset, errors="replace")
    except LookupError:
        body = raw.decode("utf-8", errors="replace")
    result = {
        "requested_url": url,
        "final_url": final_url,
        "status": status,
        "headers": headers,
        "body": body,
        "body_bytes": len(raw),
    }
    content_type = next((v for k, v in headers if k.lower() == "content-type"), "")
    if "html" in content_type.lower() or body.lstrip().lower().startswith(("<!doctype html", "<html")):
        parser = PageParser()
        try:
            parser.feed(body)
            parser.close()
            result["page_features"] = {
                "links": parser.links,
                "script_sources": parser.scripts,
                "forms": parser.forms,
                "inline_script_count": len(parser.inline_scripts),
            }
            result["inline_scripts"] = parser.inline_scripts
        except Exception as exc:
            result["html_parse_error"] = type(exc).__name__ + ": " + str(exc)
    return result


opener = urllib.request.build_opener(SameOriginRedirect())
queue = [(BASE, "initial blog page")]
seen = set()
observations = []
relationships = []

while queue:
    url, discovered_from = queue.pop(0)
    if url in seen:
        continue
    seen.add(url)
    observation = fetch(url)
    observation["discovered_from"] = discovered_from
    observations.append(observation)
    if "page_features" not in observation:
        continue

    features = observation["page_features"]
    for href in features["links"]:
        target = normalize(href, url)
        if target:
            relationships.append({"type": "link", "source": url, "target": target})
            if target not in seen:
                queue.append((target, "link observed on " + url))

    for src in features["script_sources"]:
        target = normalize(src, url)
        if target:
            relationships.append({"type": "script", "source": url, "target": target})
            if target not in seen:
                queue.append((target, "script source observed on " + url))

    for form_index, form in enumerate(features["forms"]):
        action = normalize(form["action"] or url, url)
        form_record = {
            "type": "form",
            "source": url,
            "action": action,
            "method": form["method"],
            "fields": form["fields"],
        }
        relationships.append(form_record)
        if action and form["method"] == "get":
            parts = urllib.parse.urlsplit(action)
            query = urllib.parse.parse_qsl(parts.query, keep_blank_values=True)
            query.extend(form["fields"])
            target = urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path, urllib.parse.urlencode(query), ""))
            if target not in seen:
                queue.append((target, "GET form " + str(form_index) + " observed on " + url))

    for inline_index, script in enumerate(observation.get("inline_scripts", [])):
        # Follow only same-origin URL-like strings actually present in observed JavaScript.
        for candidate in re.findall(r"[\"']([^\"']{1,500})[\"']", script):
            if not (candidate.startswith(("/", "./", "../", "?")) or re.search(r"(?:flag|file|download|read|include|upload|path|view)", candidate, re.I)):
                continue
            target = normalize(candidate, url)
            if target:
                relationships.append({"type": "inline_script_reference", "source": url, "script_index": inline_index, "target": target})
                if target not in seen:
                    queue.append((target, "URL-like reference in inline script on " + url))

print(json.dumps({
    "target": BASE,
    "method": "same-origin traversal of observed blog links, script resources, inline-script URL-like references, and GET forms",
    "observations": observations,
    "observed_relationships": relationships,
    "coverage": {
        "unique_urls_requested": len(seen),
        "external_origins_followed": False,
        "post_forms_submitted": False,
        "redirects_followed_only_within_target_origin": True,
        "note": "Bodies and response metadata are the observations. Unfollowed external links, POST forms, inaccessible resources, and runtime-generated routes remain unexamined."
    }
}, ensure_ascii=False))

