import json
import re
from html.parser import HTMLParser
from urllib.parse import urljoin

from framework_evidence import run_tool

BASE = "http://192.168.2.1/"
URLS = [
    "http://192.168.2.1/index.php?page=page1.php",
    "http://192.168.2.1/index.php?page=page2.php",
    "http://192.168.2.1/index.php?page=page3.php",
]


class PageInspector(HTMLParser):
    def __init__(self, base_url):
        super().__init__(convert_charrefs=True)
        self.base_url = base_url
        self.links = []
        self.forms = []
        self.controls = []
        self._anchor = None
        self._form = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "a":
            self._anchor = {"attributes": attrs, "text_parts": []}
        elif tag.lower() == "form":
            self._form = {"attributes": attrs, "controls": []}
            self.forms.append(self._form)
        elif tag.lower() in ("input", "button", "select", "textarea"):
            item = {"tag": tag.lower(), "attributes": attrs}
            self.controls.append(item)
            if self._form is not None:
                self._form["controls"].append(item)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_data(self, data):
        if self._anchor is not None:
            self._anchor["text_parts"].append(data)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == "a" and self._anchor is not None:
            attrs = self._anchor["attributes"]
            href = attrs.get("href")
            self.links.append({
                "href": href,
                "url": urljoin(self.base_url, href) if href else None,
                "text": " ".join(" ".join(self._anchor["text_parts"]).split()),
                "attributes": attrs,
            })
            self._anchor = None
        elif tag == "form":
            self._form = None


def envelope_stdout(envelope):
    """Return raw stdout from the evidence envelope without altering the envelope."""
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list):
            return "\n".join(
                run.get("stdout", "") for run in runs if isinstance(run, dict)
            )
        value = envelope.get("stdout")
        if isinstance(value, str):
            return value
    return ""


def final_response_body(raw):
    """Extract the body after the last HTTP header block; raw output stays preserved."""
    matches = list(re.finditer(r"(?im)^HTTP/\S+\s+\d{3}[^\r\n]*\r?\n", raw))
    if not matches:
        return None
    last = matches[-1]
    separator = re.search(r"\r?\n\r?\n", raw[last.end():])
    if separator is None:
        return None
    start = last.end() + separator.end()
    return raw[start:]


results = []
for url in URLS:
    record = {"requested_url": url}
    try:
        envelope = run_tool([
            "curl", "--silent", "--show-error", "--include", "--location",
            "--max-redirs", "10", "--max-time", "30", "--", url,
        ])
        record["evidence_envelope"] = envelope
        raw = envelope_stdout(envelope)
        body = final_response_body(raw)
        if body is None:
            record["page_inspection"] = {
                "status": "unavailable",
                "note": "No final HTTP header/body boundary could be identified; inspect the retained raw envelope.",
            }
        else:
            inspector = PageInspector(url)
            try:
                inspector.feed(body)
                inspector.close()
                record["page_inspection"] = {
                    "status": "parsed",
                    "links": inspector.links,
                    "forms": inspector.forms,
                    "controls": inspector.controls,
                }
            except Exception as exc:
                record["page_inspection"] = {
                    "status": "parser_error",
                    "error": str(exc),
                    "links_collected": inspector.links,
                    "forms_collected": inspector.forms,
                    "controls_collected": inspector.controls,
                }
    except Exception as exc:
        record["execution_error"] = {
            "type": type(exc).__name__,
            "message": str(exc),
            "note": "The request did not produce an evidence envelope.",
        }
    results.append(record)

print(json.dumps({"results": results}, ensure_ascii=False))

