import hashlib
import json
import os
from pathlib import Path

ARTIFACT = "e8260c0f2109fbc810e91a1f92998431ff362bca35e53e421668b180c00595c0.json"
EXPECTED_SHA256 = "e8260c0f2109fbc810e91a1f92998431ff362bca35e53e421668b180c00595c0"
CANDIDATES = [
    ("GET", "/robots.txt"),
    ("GET", "/sitemap.xml"),
    ("OPTIONS", "/"),
    ("HEAD", "/"),
]


def candidate_paths():
    roots = []
    for base in (Path.cwd(), Path(__file__).resolve().parent):
        try:
            current = base.resolve()
        except OSError:
            current = base
        for _ in range(6):
            if current not in roots:
                roots.append(current)
            if current.parent == current:
                break
            current = current.parent
    for fixed in (Path("/root"), Path("/")):
        if fixed not in roots:
            roots.append(fixed)

    paths = []
    for root in roots:
        paths.append(root / "llm_inputs" / ARTIFACT)
        paths.append(root / ARTIFACT)
    paths.append(Path("llm_inputs") / ARTIFACT)
    # Preserve order while removing duplicates.
    result = []
    seen = set()
    for path in paths:
        key = str(path)
        if key not in seen:
            seen.add(key)
            result.append(path)
    return result


def strings_in(value):
    if isinstance(value, dict):
        for key, item in value.items():
            yield str(key)
            yield from strings_in(item)
    elif isinstance(value, list):
        for item in value:
            yield from strings_in(item)
    elif isinstance(value, str):
        yield value


def history_entries(value):
    """Yield objects directly contained in lists named history."""
    if isinstance(value, dict):
        for key, item in value.items():
            if key.lower() == "history" and isinstance(item, list):
                for record in item:
                    if isinstance(record, dict):
                        yield record
            yield from history_entries(item)
    elif isinstance(value, list):
        for item in value:
            yield from history_entries(item)


def method_path_mentioned(record, method, path):
    text = "\n".join(strings_in(record))
    upper = text.upper()
    if method not in upper:
        return False
    if path != "/":
        return path in text
    # For root requests, require an explicit method/root token rather than an
    # arbitrary slash elsewhere in the record.
    markers = (
        method + " /", method + " http://192.168.2.1/",
        method + " https://192.168.2.1/",
        "\"method\": \"" + method + "\"",
    )
    return any(marker.upper() in upper for marker in markers)


def completeness_markers(value):
    found = []
    interesting = {"complete", "is_complete", "history_complete", "truncated", "partial"}

    def walk(obj, location="$", depth=0):
        if depth > 30:
            return
        if isinstance(obj, dict):
            for key, item in obj.items():
                if str(key).lower() in interesting and isinstance(item, (bool, str, int)):
                    found.append({"path": location + "." + str(key), "value": item})
                walk(item, location + "." + str(key), depth + 1)
        elif isinstance(obj, list):
            for index, item in enumerate(obj):
                walk(item, location + "[" + str(index) + "]", depth + 1)

    walk(value)
    return found


def main():
    tried = candidate_paths()
    source = None
    access_errors = []
    for path in tried:
        try:
            if path.is_file():
                source = path
                break
        except OSError as exc:
            access_errors.append({"path": str(path), "error": str(exc)})

    if source is None:
        print(json.dumps({
            "status": "artifact_not_found",
            "artifact": ARTIFACT,
            "attempted_paths": [str(p) for p in tried],
            "access_errors": access_errors,
            "finding": "The supplied archive reference could not be resolved at the checked exact paths; request history and its completeness remain unknown.",
            "requests_issued": 0,
        }, ensure_ascii=False))
        return

    try:
        raw = source.read_bytes()
        actual_sha = hashlib.sha256(raw).hexdigest()
        document = json.loads(raw.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        print(json.dumps({
            "status": "artifact_read_or_parse_error",
            "artifact_path": str(source),
            "error": str(exc),
            "requests_issued": 0,
        }, ensure_ascii=False))
        return

    if isinstance(document, dict) and "prior_observations" in document:
        observations = document["prior_observations"]
        observations_source = '$["prior_observations"]'
    else:
        observations = document
        observations_source = "artifact root (prior_observations key not present)"

    records = list(history_entries(observations))
    results = []
    for method, path in CANDIDATES:
        matches = [r for r in records if method_path_mentioned(r, method, path)]
        results.append({
            "method": method,
            "path": path,
            "matching_history_record_count": len(matches),
            "records": matches,
            "interpretation": "Matching recorded history entries are shown; zero matches does not establish that the request was never made.",
        })

    markers = completeness_markers(observations)
    sha_matches = actual_sha == EXPECTED_SHA256
    print(json.dumps({
        "status": "inspected",
        "artifact_path": str(source),
        "artifact_sha256": actual_sha,
        "expected_sha256": EXPECTED_SHA256,
        "artifact_hash_matches_reference": sha_matches,
        "observations_source": observations_source,
        "history_record_count": len(records),
        "candidate_requests": results,
        "explicit_completeness_markers": markers,
        "history_completeness": "explicit markers are reported above; absent an applicable explicit marker, completeness is unknown",
        "requests_issued": 0,
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

