import hashlib
import json
import os
from pathlib import Path

REFERENCE = "llm_inputs/97c015266fbe69a6e6c336edb1d66c54a2a758cbe8f2d291886c6bf397d54e34.json"
TARGET = "192.168.2.1"


def candidate_paths():
    rel = Path(REFERENCE)
    roots = [Path.cwd(), *Path.cwd().parents, Path("/root"), Path("/tmp"), Path("/workspace"), Path("/mnt/data"), Path("/artifacts"), Path("/archive")]
    seen = set()
    for root in roots:
        path = (root / rel).resolve()
        key = str(path)
        if key not in seen:
            seen.add(key)
            yield path


def contains_http_record(value):
    text = json.dumps(value, ensure_ascii=False, default=str).lower()
    return TARGET in text and any(term in text for term in ("http", "https", "curl", "request", "response", "url"))


def extract_records(document):
    found = []

    def visit(value, path):
        if isinstance(value, dict):
            node_id = str(value.get("node_id", ""))
            record_text = json.dumps(value, ensure_ascii=False, default=str).lower()
            named_http_record = "http" in node_id.lower() or "enumerate_http" in record_text
            has_execution = "execution_result" in value or "requests" in value or "request" in value
            if has_execution and (named_http_record or contains_http_record(value)):
                found.append({"source_path": path, "record": value})
                return
            for key, child in value.items():
                visit(child, path + "." + str(key))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                visit(child, path + "[" + str(index) + "]")

    visit(document, "$" )
    return found


def main():
    checked = []
    artifact_path = None
    for path in candidate_paths():
        checked.append(str(path))
        if path.is_file():
            artifact_path = path
            break

    if artifact_path is None:
        print(json.dumps({
            "status": "artifact_not_found",
            "reference": REFERENCE,
            "checked_paths": checked,
            "requests_sent": 0,
            "limitation": "The specified file was not present at the checked reference-relative locations; this does not establish that it is unavailable elsewhere in the archive."
        }, ensure_ascii=False))
        return

    raw = artifact_path.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    try:
        document = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        print(json.dumps({
            "status": "parse_error",
            "reference": REFERENCE,
            "resolved_path": str(artifact_path),
            "sha256": digest,
            "byte_length": len(raw),
            "error": str(exc),
            "requests_sent": 0
        }, ensure_ascii=False))
        return

    records = extract_records(document)
    print(json.dumps({
        "status": "retrieved_and_parsed",
        "reference": REFERENCE,
        "resolved_path": str(artifact_path),
        "sha256": digest,
        "byte_length": len(raw),
        "http_history_record_count": len(records),
        "http_history_records": records,
        "requests_sent": 0,
        "extraction_note": "Records are copied from the retrieved artifact; an empty list means no matching record was extracted, not that no HTTP requests occurred."
    }, ensure_ascii=False, default=str))


if __name__ == "__main__":
    main()

