import json
import os

REFERENCE = "97c015266fbe69a6e6c336edb1d66c54a2a758cbe8f2d291886c6bf397d54e34"
TARGET = "192.168.2.1"
ROOTS = ["/archive", "/artifacts", "/mnt/data", "/workspace", "/tmp", "/root"]
SKIP_DIRS = {".cache", ".git", "node_modules", "proc", "sys", "dev"}


def is_index_name(name):
    low = name.lower()
    return any(word in low for word in ("index", "manifest", "catalog", "archive")) and low.endswith((".json", ".jsonl", ".txt", ".csv", ".db", ".sqlite", ".sqlite3"))


def walk_root(root, errors):
    """Walk an existing candidate root without following symlinks."""
    if not os.path.isdir(root):
        return
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        # Generated scripts are not archive evidence and were among the earlier checked paths.
        if current == "/root":
            dirs[:] = [d for d in dirs if d != "scripts"]
        for name in files:
            path = os.path.join(current, name)
            yield path


def scan_index(path):
    hits = []
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            for number, line in enumerate(stream, 1):
                if REFERENCE in line or ("llm_inputs/" + REFERENCE) in line:
                    hits.append({"line": number, "text": line.rstrip()[:2000]})
    except (OSError, UnicodeError) as exc:
        return [], str(exc)
    return hits, ""


def extract_http_history(value, path="$", out=None):
    if out is None:
        out = []
    if isinstance(value, dict):
        keys = {str(k).lower() for k in value}
        looks_like_request = bool(keys & {"url", "uri", "request", "method", "path"})
        serialized = json.dumps(value, ensure_ascii=False, default=str)
        if looks_like_request and (TARGET in serialized or any(k in keys for k in ("url", "uri", "request"))):
            out.append({"source_path": path, "record": value})
        for key, child in value.items():
            extract_http_history(child, path + "." + str(key), out)
    elif isinstance(value, list):
        for i, child in enumerate(value):
            extract_http_history(child, "%s[%d]" % (path, i), out)
    return out


def main():
    examined_roots = []
    missing_roots = []
    file_count = 0
    artifact_paths = []
    index_paths = []
    errors = []
    seen = set()

    for root in ROOTS:
        if not os.path.isdir(root):
            missing_roots.append(root)
            continue
        examined_roots.append(root)
        for path in walk_root(root, errors):
            if path in seen:
                continue
            seen.add(path)
            file_count += 1
            name = os.path.basename(path)
            if name == REFERENCE or name == REFERENCE + ".json":
                artifact_paths.append(path)
            if is_index_name(name):
                index_paths.append(path)

    index_hits = []
    for path in index_paths:
        hits, error = scan_index(path)
        if hits:
            index_hits.append({"path": path, "matches": hits})
        if error:
            errors.append({"path": path, "error": error})

    artifacts = []
    for path in artifact_paths:
        item = {"path": path}
        try:
            with open(path, "r", encoding="utf-8") as stream:
                data = json.load(stream)
            item["parse_status"] = "parsed_json"
            item["http_history_records"] = extract_http_history(data)
            item["top_level_keys"] = list(data.keys()) if isinstance(data, dict) else None
            item["target_mentions"] = TARGET in json.dumps(data, ensure_ascii=False, default=str)
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            item["parse_status"] = "parse_or_read_error"
            item["error"] = str(exc)
        artifacts.append(item)

    result = {
        "status": "archive_lookup_completed",
        "reference": REFERENCE,
        "target": TARGET,
        "requests_sent": 0,
        "search_method": "Recursive read-only filename search and textual search of files named as archive indexes, manifests, catalogs, or indexes under candidate roots.",
        "examined_roots": examined_roots,
        "missing_roots": missing_roots,
        "files_examined": file_count,
        "index_files_examined": len(index_paths),
        "index_matches": index_hits,
        "matching_artifacts": artifacts,
        "errors": errors,
        "coverage_limitation": "Search covers only the listed candidate roots, excludes /root/scripts and common cache/VCS/system directories, does not follow symlinks, and only searches reference text in files whose names identify them as indexes/manifests/catalogs/archive files. No match does not establish unavailability elsewhere."
    }
    if not artifacts and not index_hits:
        result["outcome"] = "not_found_in_examined_roots_and_indexes"
    elif artifacts:
        result["outcome"] = "artifact_found_and_parsed_or_parse_error_reported"
    else:
        result["outcome"] = "reference_found_in_index_without_artifact"
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

