import json
import os
from pathlib import Path

ARCHIVE = "llm_inputs/1f32c76ba9c1421c3d75c642f868e0f2978a8b4c90779d0f9a99d71ee0c68fd1.json"
TARGET = "192.168.2.1"
REQUESTS = [
    ("GET", "/robots.txt"),
    ("GET", "/sitemap.xml"),
    ("OPTIONS", "/"),
    ("HEAD", "/"),
]


def as_text(value):
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    except (TypeError, ValueError):
        return repr(value)


def history_entries(value, location="$", ancestors=()):
    """Yield history-like execution records without assuming a particular schema."""
    if isinstance(value, dict):
        node_id = value.get("node_id")
        if isinstance(node_id, str) and ("execution_result" in value or "stdout" in value):
            yield location, value
        for key, child in value.items():
            yield from history_entries(child, location + "." + str(key), ancestors + (value,))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from history_entries(child, location + "[" + str(index) + "]", ancestors)


def main():
    # Resolve the supplied reference as-is, then relative to the likely working roots.
    candidates = [Path(ARCHIVE)]
    for root in (Path.cwd(), Path("/root"), Path("/tmp")):
        candidate = root / ARCHIVE
        if candidate not in candidates:
            candidates.append(candidate)

    examined = []
    source = None
    for candidate in candidates:
        try:
            if candidate.is_file():
                source = candidate
                break
            examined.append({"path": str(candidate), "status": "not_found"})
        except OSError as exc:
            examined.append({"path": str(candidate), "status": "error", "error": str(exc)})

    if source is None:
        print(json.dumps({
            "archive_reference": ARCHIVE,
            "archive_status": "not_readable_at_attempted_paths",
            "attempted_paths": examined,
            "request_findings": [
                {"method": method, "path": path, "status": "unresolved"}
                for method, path in REQUESTS
            ],
            "coverage_note": "The supplied reference was not found at the attempted exact-reference paths; this does not establish whether records exist elsewhere.",
        }, ensure_ascii=False))
        return

    try:
        raw = source.read_bytes()
    except OSError as exc:
        print(json.dumps({"archive_reference": ARCHIVE, "resolved_path": str(source),
                          "archive_status": "read_error", "error": str(exc)}, ensure_ascii=False))
        return

    try:
        document = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        print(json.dumps({"archive_reference": ARCHIVE, "resolved_path": str(source),
                          "archive_status": "parse_error", "error": str(exc),
                          "bytes_read": len(raw)}, ensure_ascii=False))
        return

    matches = []
    findings = { (method, path): [] for method, path in REQUESTS }
    for location, record in history_entries(document):
        text = as_text(record)
        if TARGET not in text:
            continue
        for method, path in REQUESTS:
            # Require both method and path to occur in this recorded entry.
            if method in text.upper() and path in text:
                findings[(method, path)].append(location)
                matches.append({"location": location, "method_path_match": method + " " + path,
                                "record": record})

    request_findings = []
    for method, path in REQUESTS:
        locations = findings[(method, path)]
        request_findings.append({
            "method": method,
            "path": path,
            "status": "recorded_entry_found" if locations else "not_established_in_matching_history_entries",
            "matching_record_locations": locations,
        })

    print(json.dumps({
        "archive_reference": ARCHIVE,
        "resolved_path": str(source),
        "archive_status": "read_and_parsed",
        "bytes_read": len(raw),
        "request_findings": request_findings,
        "matching_history_records": matches,
        "coverage_note": "Only parsed history entries containing the target address and the specified method/path text are included. A missing match is not evidence that the request was never made; inspect any archive truncation or alternate record format before drawing that conclusion.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

