import json
import os
import sys
from urllib.parse import urlsplit

REFERENCE = "llm_inputs/1f32c76ba9c1421c3d75c642f868e0f2978a8b4c90779d0f9a99d71ee0c68fd1.json"
BASENAME = os.path.basename(REFERENCE)
CANDIDATES = {
    ("GET", "/robots.txt"),
    ("GET", "/sitemap.xml"),
    ("OPTIONS", "/"),
    ("HEAD", "/"),
}
SKIP_DIRS = {"proc", "sys", "dev"}

found = []
walk_errors = []
scanned_roots = []

# Search accessible filesystem locations for the archive's exact filename rather
# than retrying the previously checked exact-reference paths.
for root, dirs, files in os.walk("/", topdown=True, followlinks=False,
                                  onerror=lambda exc: walk_errors.append(str(exc))):
    dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
    if root == "/":
        scanned_roots.append(root)
    if BASENAME in files:
        found.append(os.path.join(root, BASENAME))


def direct_candidate(record):
    if not isinstance(record, dict):
        return None
    method = record.get("method") or record.get("http_method")
    path_value = record.get("path") or record.get("request_path") or record.get("url")
    if not isinstance(method, str) or not isinstance(path_value, str):
        return None
    method = method.upper()
    path = urlsplit(path_value).path or "/"
    if (method, path) in CANDIDATES:
        return method, path
    return None


def collect_records(value, results):
    if isinstance(value, dict):
        candidate = direct_candidate(value)
        if candidate:
            results.append({"candidate": {"method": candidate[0], "path": candidate[1]},
                            "record": value})
            return
        for child in value.values():
            collect_records(child, results)
    elif isinstance(value, list):
        for child in value:
            collect_records(child, results)

result = {
    "archive_reference": REFERENCE,
    "search": {
        "method": "filesystem filename discovery",
        "root": "/",
        "follow_symlinks": False,
        "excluded_virtual_directories": sorted(SKIP_DIRS),
        "permission_or_walk_errors": len(walk_errors),
        "walk_error_samples": walk_errors[:20],
    },
    "archive_status": "not_found",
    "archive_matches": [],
    "request_records": [],
    "request_findings": [
        {"method": m, "path": p, "status": "unresolved"}
        for m, p in sorted(CANDIDATES)
    ],
}

for path in found:
    entry = {"path": path}
    try:
        with open(path, "r", encoding="utf-8") as stream:
            artifact = json.load(stream)
        records = []
        collect_records(artifact, records)
        entry["read_status"] = "readable_json"
        entry["top_level_type"] = type(artifact).__name__
        entry["matching_record_count"] = len(records)
        result["archive_matches"].append(entry)
        result["request_records"].extend(
            [{"archive_path": path, **record} for record in records]
        )
    except Exception as exc:
        entry["read_status"] = "unreadable_or_invalid_json"
        entry["error"] = f"{type(exc).__name__}: {exc}"
        result["archive_matches"].append(entry)

if found:
    readable = [e for e in result["archive_matches"] if e["read_status"] == "readable_json"]
    result["archive_status"] = "readable" if readable else "found_but_unreadable"

observed = {(r["candidate"]["method"], r["candidate"]["path"])
            for r in result["request_records"]}
for finding in result["request_findings"]:
    if (finding["method"], finding["path"]) in observed:
        finding["status"] = "record_recovered"

result["coverage_note"] = (
    "Only matching request records present in readable archive JSON are reported. "
    "Unresolved candidates were not recovered by this search; that does not establish "
    "whether they were requested. Filesystem walk errors may limit discovery."
)
print(json.dumps(result, ensure_ascii=False))

