import json
import ipaddress
import sys

TARGET = "192.168.2.1"
PORTS = "53,67,68,69,123,137,138,161,162,500,514,520,631,1434,1900,4500,5353,5355,11211"


def emit(value):
    print(json.dumps(value, sort_keys=True, ensure_ascii=False))


def main():
    target = str(ipaddress.ip_address(TARGET))
    emit({
        "purpose": "Review supplied prior UDP evidence, then perform a focused supplemental UDP service-identification scan.",
        "target": target,
        "prior_evidence_review": {
            "available_facts": [
                "The supplied prior-observation preview includes an earlier UDP review/scan action that timed out after approximately 120 seconds.",
                "That attempt had empty stdout and stderr, no exit code, and no parsed tool output.",
                "The parent dependency describes prior UDP survey evidence as limited, but supplies no actual port list or method details."
            ],
            "unknowns": [
                "The exact ports and methods in the prior survey cannot be recovered from the supplied partial preview.",
                "Whether any ports selected for this supplemental scan were previously covered is unknown; they are treated as uncertain, not confirmed uncovered.",
                "No conclusions are made about ports omitted from this focused scan."
            ],
            "evidence_reference": "f7188289476d107eb957504412d2db180319b74711b3ef4ba31ed9609b74df2b"
        },
        "supplemental_scan_scope": {
            "udp_ports": PORTS,
            "method": "Nmap UDP scan with light service/version identification, one retry, numeric output, and a 90-second host timeout.",
            "coverage_limit": "Only the explicitly listed UDP ports on the in-scope candidate are examined."
        }
    })

    try:
        import framework_evidence
    except Exception as exc:
        emit({
            "scan_status": "not_started",
            "error": "Could not import the supplied framework_evidence helper.",
            "detail": str(exc)
        })
        return 2

    argv = [
        "nmap", "-sU", "-sV", "--version-light", "--max-retries", "1",
        "--host-timeout", "90s", "-n", "-Pn", "-p", PORTS, target
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        emit({
            "scan_status": "helper_error",
            "command": argv,
            "error": str(exc)
        })
        return 1

    # Retain and print the helper's returned evidence envelope without
    # summarizing away raw streams or structured parser observations.
    if isinstance(envelope, str):
        try:
            print(json.dumps(json.loads(envelope), sort_keys=True, ensure_ascii=False))
        except Exception:
            emit({"scan_status": "helper_returned_non_json_text", "raw_result": envelope})
    else:
        emit(envelope)
    return 0


if __name__ == "__main__":
    sys.exit(main())

